<?php
/**
 * Công cụ tự động khôi phục toàn diện & Khắc phục lỗi Mướp Đắng 1 Chạm
 * Dành cho Hosting: muopdangcungcovingot.io.vn
 */
header('Content-Type: text/html; charset=utf-8');

$b64_functions_comp = '';
$b64_header         = '';
$b64_story_card     = '';
$b64_404            = '';

$results = [];
$errors  = [];

// 1. Tìm thư mục gốc website & thư mục theme
$base_dir = __DIR__;
$wp_load_candidates = [
    $base_dir . '/wp-load.php',
    $base_dir . '/core/wp-load.php',
    dirname($base_dir) . '/wp-load.php',
    dirname($base_dir) . '/core/wp-load.php',
];

$wp_load_path = null;
foreach ($wp_load_candidates as $cand) {
    if (file_exists($cand)) {
        $wp_load_path = $cand;
        break;
    }
}

$theme_dir_candidates = [
    $base_dir . '/wp-content/themes/muop-dang',
    dirname($base_dir) . '/wp-content/themes/muop-dang',
    $base_dir . '/core/wp-content/themes/muop-dang',
    $base_dir . '/themes/muop-dang',
];

$theme_dir = null;
foreach ($theme_dir_candidates as $cand) {
    if (is_dir($cand)) {
        $theme_dir = $cand;
        break;
    }
}

// Nếu chưa có thư mục theme thì tự tạo luôn
if (!$theme_dir) {
    $possible_theme_parent = is_dir($base_dir . '/wp-content/themes') ? $base_dir . '/wp-content/themes' : null;
    if ($possible_theme_parent) {
        $theme_dir = $possible_theme_parent . '/muop-dang';
        @mkdir($theme_dir, 0755, true);
    }
}

$action = isset($_GET['action']) ? $_GET['action'] : '';

// Xử lý tự xóa file
if ($action === 'delete_self') {
    @unlink(__FILE__);
    echo '<div style="font-family:sans-serif;text-align:center;padding:50px;"><h2>Đã xóa file khac_phuc_loi.php an toàn!</h2><p><a href="/">Quay lại Trang Chủ</a></p></div>';
    exit;
}

// Tự động khôi phục các file cốt lõi (functions.php, header.php, story-card.php, 404.php)
if ($action === 'fix_all' || $action === 'auto_all') {
    if ($theme_dir && is_dir($theme_dir)) {
        // 1. Khôi phục functions.php
        $target_func = $theme_dir . '/functions.php';
        $raw_func = gzuncompress(base64_decode($b64_functions_comp));
        if ($raw_func && @file_put_contents($target_func, $raw_func)) {
            $results[] = 'Đã khôi phục thành công file <code>functions.php</code> (' . strlen($raw_func) . ' bytes) vào thư mục theme!';
        } else {
            $errors[] = 'Không thể ghi file ' . $target_func . '. Vui lòng kiểm tra quyền thư mục (CHMOD 755).';
        }

        // 2. Cập nhật header.php
        $target_header = $theme_dir . '/header.php';
        $raw_header = base64_decode($b64_header);
        if ($raw_header && @file_put_contents($target_header, $raw_header)) {
            $results[] = 'Đã cập nhật file <code>header.php</code> (Tích hợp Fallback CSS & chống Fatal Error)!';
        }

        // 3. Cập nhật story-card.php
        $target_sc = $theme_dir . '/template-parts/story-card.php';
        $sc_dir = dirname($target_sc);
        if (!is_dir($sc_dir)) @mkdir($sc_dir, 0755, true);
        $raw_sc = base64_decode($b64_story_card);
        if ($raw_sc && @file_put_contents($target_sc, $raw_sc)) {
            $results[] = 'Đã cập nhật file <code>story-card.php</code> (bảo vệ hàm lượt xem an toàn)!';
        }

        // 4. Tạo file 404.php
        $target_404 = $theme_dir . '/404.php';
        $raw_404 = base64_decode($b64_404);
        if ($raw_404 && @file_put_contents($target_404, $raw_404)) {
            $results[] = 'Đã tạo file giao diện <code>404.php</code> chuẩn đẹp!';
        }
    } else {
        $errors[] = 'Không tìm thấy thư mục theme muop-dang trên hosting!';
    }
}

// Tự động giải nén file ZIP nếu có trên server
if ($action === 'unzip_all' || $action === 'auto_all') {
    $zip_files = glob($base_dir . '/*.zip');
    $zip_files = array_merge($zip_files, glob($base_dir . '/wp-content/themes/*.zip'));
    
    $extracted_count = 0;
    if (class_exists('ZipArchive') && !empty($zip_files)) {
        foreach ($zip_files as $zf_path) {
            $bname = basename($zf_path);
            if (strpos($bname, 'muop') !== false || strpos($bname, 'cap_nhat') !== false) {
                $zip = new ZipArchive();
                if ($zip->open($zf_path) === TRUE) {
                    $dest = $theme_dir;
                    if (strpos($bname, 'goc_website') !== false) {
                        $dest = $base_dir;
                    } elseif (strpos($bname, 'muop-dang.zip') !== false) {
                        $dest = dirname($theme_dir);
                    }
                    
                    if ($dest && is_dir($dest)) {
                        $zip->extractTo($dest);
                        $zip->close();
                        $results[] = 'Đã giải nén gói <strong>' . $bname . '</strong> vào <code>' . $dest . '</code>!';
                        $extracted_count++;
                    }
                }
            }
        }
    }
}

// Nạp WordPress, đăng ký Post Types và làm mới Permalinks
$wp_loaded = false;
if ($wp_load_path) {
    try {
        require_once $wp_load_path;
        $wp_loaded = true;
        
        global $wpdb;
        if ($wpdb) {
            $table_splitter = $wpdb->prefix . 'muop_splitter_history';
            $wpdb->query("CREATE TABLE IF NOT EXISTS `$table_splitter` (
              `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
              `session_key` varchar(64) NOT NULL,
              `user_id` bigint(20) unsigned NOT NULL,
              `title` varchar(255) NOT NULL,
              `total_chapters` int(11) NOT NULL DEFAULT '0',
              `total_words` int(11) NOT NULL DEFAULT '0',
              `avg_words` int(11) NOT NULL DEFAULT '0',
              `target_words` int(11) NOT NULL DEFAULT '2500',
              `chapters_json` longtext NOT NULL,
              `created_at` datetime NOT NULL,
              PRIMARY KEY (`id`),
              KEY `idx_user` (`user_id`),
              KEY `idx_created` (`created_at`)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;");
            
            if (function_exists('update_option')) {
                update_option('posts_per_page', 24);
            }
            $results[] = 'Đã đồng bộ Database: Bảng tách chương đa thiết bị & thiết lập 24 truyện/trang!';
        }

        // Làm mới permalinks rewrite rules
        if (function_exists('flush_rewrite_rules')) {
            if (function_exists('muop_register_post_types')) {
                muop_register_post_types();
            }
            flush_rewrite_rules(true);
            $results[] = 'Đã làm mới quy tắc điều hướng (Rewrite rules) & đăng ký lại Post Type Truyện thành công!';
        }

        if (function_exists('delete_transient')) {
            delete_transient('muop_all_genres_list');
            $results[] = 'Đã xóa transient cache thành công!';
        }
    } catch (Throwable $e) {
        $errors[] = 'Lỗi nạp WordPress: ' . $e->getMessage();
    }
}

$func_exists_on_disk = $theme_dir && file_exists($theme_dir . '/functions.php');
?>
<!DOCTYPE html>
